import{I as o,o as h,c as m,j as e,a as n,J as a,w as s,b6 as i,cx as y,cy as f,cz as b,cA as k,cB as w,cC as v,cD as I,cE as x,cF as q,cG as A,cH as _,cI as P,cJ as C,cK as T,cL as S,cM as E,cN as D,cO as W,cP as B,k as F}from"./chunks/framework.COUcLbTA.js";import{r as R}from"./chunks/relatedArticles.CW_ys7fD.js";const M={style:{margin:"50px 0"}},O={style:{margin:"50px 0"}},L={style:{margin:"50px 0"}},j={style:{margin:"50px 0"}},G=JSON.parse('{"title":"Build a Prototype Hands-On - From Business Analysis to Multi-Page Product Prototype Implementation","description":"Experience the complete loop from business analysis to multi-page product prototype implementation. Learn how to ask business questions, break down requirements, use an AI IDE to generate single-page and multi-page apps, and polish and test prototypes.","frontmatter":{"title":"Build a Prototype Hands-On - From Business Analysis to Multi-Page Product Prototype Implementation","description":"Experience the complete loop from business analysis to multi-page product prototype implementation. Learn how to ask business questions, break down requirements, use an AI IDE to generate single-page and multi-page apps, and polish and test prototypes."},"headers":[],"relativePath":"en/stage-1/building-prototype/index.md","filePath":"en/stage-1/building-prototype/index.md"}'),N={name:"en/stage-1/building-prototype/index.md"},U=Object.assign(N,{setup(V){const u="About <strong>8 hours</strong>",c=R["en/stage-1/building-prototype"]??[];return(z,t)=>{const d=o("ChapterIntroduction"),r=o("StepBar"),l=o("ClientOnly"),p=o("el-card"),g=o("RelatedArticlesSection");return h(),m("div",null,[t[5]||(t[5]=e("h1",{id:"beginner-3-build-a-prototype-hands-on",tabindex:"-1"},[n("Beginner 3: Build a Prototype Hands-On "),e("a",{class:"header-anchor",href:"#beginner-3-build-a-prototype-hands-on","aria-label":"Permalink to “Beginner 3: Build a Prototype Hands-On”"},"​")],-1)),t[6]||(t[6]=e("h2",{id:"chapter-introduction",tabindex:"-1"},[n("Chapter Introduction "),e("a",{class:"header-anchor",href:"#chapter-introduction","aria-label":"Permalink to “Chapter Introduction”"},"​")],-1)),a(d,{duration:u,tags:["Business Analysis","Prototype Design","AI-Assisted Coding","Multi-Page Applications"],coreOutput:"1 E-commerce Asset Workbench Prototype",expectedOutput:"An Interactive Web Prototype"},{default:s(()=>[...t[0]||(t[0]=[e("p",null,[n("In the previous chapter, we learned how to "),e("strong",null,"find a great idea"),n(" - starting from user needs and finding directions people are willing to pay for. But finding direction is only step one. "),e("strong",null,"What really tests a product manager is: how to turn vague requirements into a usable product.")],-1),e("p",null,[n("In this chapter, we solve one "),e("strong",null,"real-world problem"),n(': your boss throws one sentence at you, "Use AI to improve the efficiency of publishing products to e-commerce platforms." How do you turn that into a '),e("strong",null,"usable product prototype"),n("?")],-1),e("p",null,[n("Unlike building Snake or a calculator, "),e("strong",null,"real business work cannot rely on imagined features"),n(":")],-1),e("ol",null,[e("li",null,[e("strong",null,"Clarify pain points"),n(": talk to operations and dig out the "),e("strong",null,"real pain points"),n(' hidden behind the vague phrase "improve efficiency"')]),e("li",null,[e("strong",null,"Prioritize"),n(": among many problems, solve the "),e("strong",null,"most painful one"),n(" first, instead of trying to do everything at once")]),e("li",null,[e("strong",null,"Validate quickly"),n(": use an AI IDE to build a "),e("strong",null,"single-page prototype"),n(" first; once it works, expand to multiple pages")]),e("li",null,[e("strong",null,"Deliver something usable"),n(": finally deliver an "),e("strong",null,"e-commerce asset workbench that can be demonstrated and operated")])],-1),e("p",null,[n("We will learn the shift from "),e("strong",null,"building toys to building applications"),n(", and learn how to "),e("strong",null,"empathize and think from real customer needs"),n(".")],-1)])]),_:1}),t[7]||(t[7]=e("div",{class:"info custom-block"},[e("p",{class:"custom-block-title"},"Note"),e("p",null,"This chapter contains some business terms. If you do not understand one, ask AI for an explanation.")],-1)),e("div",M,[a(l,null,{default:s(()=>[a(r,{active:0,items:[{title:"Requirement Analysis",description:"From vague to concrete"},{title:"Single-Page Validation",description:"Implement the core gameplay"},{title:"Multi-Page Expansion",description:"Complete application structure"},{title:"Polish and Refine",description:"Improve user experience"}]})]),_:1})]),t[8]||(t[8]=i('<h2 id="_1-define-requirements-before-writing-code" tabindex="-1">1. Define Requirements Before Writing Code <a class="header-anchor" href="#_1-define-requirements-before-writing-code" aria-label="Permalink to “1. Define Requirements Before Writing Code”">​</a></h2><p>In earlier tutorials, we used AI IDE tools to quickly generate Snake and mini-games. But those are toy projects and are not directly useful in daily work and life. If we want AI capability to truly create value, we should combine vibe coding with real work and life scenarios.</p><p>In the previous chapter, we learned how to find <strong>ideas people are willing to pay for</strong>, but finding direction is only the beginning. In real product work, you will realize: <strong>there is a huge gap between knowing &quot;what to build&quot; and knowing &quot;how to build it.&quot;</strong></p><p>That gap is <strong>making requirements concrete</strong>.</p><p>For example, in class or personal projects, we often start from the simplest executable function:</p><ul><li>&quot;Build a board that lists tasks.&quot;</li><li>&quot;Help me build a drawing tool.&quot;</li><li>&quot;Help me build software to collect questionnaires.&quot;</li></ul><p>These are often just tools or isolated feature modules, and sometimes not even a clearly defined business problem. More importantly, <strong>these ideas are often &quot;I think this is useful,&quot; not &quot;users truly need this.&quot;</strong></p><p>In enterprise projects or startup projects, product managers and engineers usually start from larger business goals. For example, assume this scenario:</p>',8)),a(p,{shadow:"hover",style:{"border-left":"5px solid #409EFF","background-color":"#ecf5ff",margin:"20px 0"}},{default:s(()=>[...t[1]||(t[1]=[e("div",{style:{"font-weight":"bold",color:"#303133","margin-bottom":"10px"}},"🛍️ Business Scenario:",-1),e("div",{style:{color:"#606266","line-height":"1.6"}},[e("p",null,"You are an e-commerce operations product manager at a store. Your boss gives you a vague but high-pressure assignment:"),e("p",{style:{"font-style":"italic","margin-top":"10px"}},'"Everyone on public channels is using AI to make images and copywriting, and it looks easy. Set this up for us so we can launch new products on Douyin e-commerce more efficiently."')],-1)])]),_:1}),t[9]||(t[9]=i(`<p>You might think, &quot;Boss, you are dreaming again.&quot; In real work, though, this kind of one-sentence, vague directive is very common. To become a capable professional (or better, an early-stage startup CEO), we must learn how to move from building personal tools to building real product prototypes.</p><p>Since we already learned AI IDE usage, you may think this requirement is easy: give AI a prompt and let the agent do everything:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please refer to my requirement xxxx,</span></span>
<span class="line"><span>help me design an e-commerce asset workbench,</span></span>
<span class="line"><span>including generation and management of product descriptions, images, videos, and other assets.</span></span></code></pre></div><p>If you excitedly convert this straight into a prototype and send it to your boss - congratulations, your quarterly bonus may disappear.</p><p><strong>Why? This is exactly the core pain point we need to solve:</strong></p><p>Previously, when learning AI IDE tools, we mostly built <strong>toy projects for ourselves</strong> like Snake and calculators: simple features, clear personal goals, and &quot;works for me&quot; is enough. But <strong>real business scenarios are completely different</strong>:</p><ul><li><strong>You are not the user</strong>: the boss says &quot;improve efficiency,&quot; but you do not know how operations actually works daily or where the bottleneck is.</li><li><strong>AI does not understand your business either</strong>: if you give AI a vague requirement, it can only guess from generic knowledge. The result may look plausible but be unusable.</li><li><strong>A good idea is not the same as a good product</strong>: you may think &quot;add AI generation&quot; is cool, but users may not need it, or it might create more friction.</li></ul><p><strong>That is why we must learn &quot;from having an idea to understanding users.&quot;</strong> Only when your idea truly solves someone else&#39;s problem, and you ask questions and deeply understand business context, can you produce real value. (A good idea can be even more important than good technology.)</p><h3 id="_1-1-from-imagination-to-reality-learn-to-ask-the-business" tabindex="-1">1.1 From Imagination to Reality: Learn to Ask the Business <a class="header-anchor" href="#_1-1-from-imagination-to-reality-learn-to-ask-the-business" aria-label="Permalink to “1.1 From Imagination to Reality: Learn to Ask the Business”">​</a></h3><div class="info custom-block"><p class="custom-block-title">💡 Clarify first: what is a requirement? what is business?</p><p><strong>A requirement</strong> is what users truly want: the problem they encounter and want solved.<br> For example, &quot;my boss wants me to launch products faster&quot; is a requirement.</p><p><strong>Business</strong> is what users actually do every day: their operational workflow.<br> For example, daily e-commerce operations tasks include launching products, changing prices, making images, reviewing data, and more.</p><p><strong>Why focus on business?</strong><br> If you do not understand the business, you may build something that &quot;looks good but nobody uses.&quot; Only when you understand users&#39; daily workflow and bottlenecks can you build something truly helpful.</p></div><p>From the simplest angle, ask yourself:</p><ul><li>When the boss says &quot;<strong>improve efficiency</strong>,&quot; what does that mean exactly? <strong>Faster delivery</strong>? <strong>Lower cost</strong>? <strong>Higher sales</strong>?</li><li>How are products launched now? <strong>Where does the current process break down</strong>?</li><li>How many <strong>new products</strong> are launched each day? How many <strong>images</strong> and how much <strong>text</strong> are needed per product?</li><li>Which tasks in the current workflow are the <strong>most painful</strong> and <strong>most disliked</strong>?</li></ul><p>These are still assumptions. We need to ask frontline Douyin e-commerce practitioners directly: &quot;Where are your actual difficulties, and what do you care about most?&quot; This gives more accurate answers.</p><div class="info custom-block"><p class="custom-block-title">📋 Real business interview findings</p><p>We asked e-commerce operators and heard:</p><p><strong>1. Too much, too fragmented</strong></p><ul><li>One person handles multiple stores, each with many products</li><li>Daily work keeps switching between <strong>launching products</strong>, <strong>changing prices</strong>, <strong>creating images</strong>, and <strong>checking data</strong></li></ul><p><strong>2. Content is iterative, not one-shot</strong></p><ul><li>First use <strong>vendor-provided images</strong>, <strong>historical assets</strong>, or <strong>reference screenshots</strong> to quickly launch</li><li>Spend a small budget to test and <strong>see if sales happen</strong></li><li>Only for <strong>products that perform well</strong> do they invest deeply in image design, detail pages, and video</li></ul></div><p>After interviewing the business side, we might feel, &quot;Now we can build the perfect prototype.&quot; Still wrong. If we try to satisfy everything at once, the product becomes huge and impossible to land within course time. We still need to narrow and prioritize core pain points.</p><h3 id="_1-2-from-divergence-to-convergence-lock-the-core-pain-point-and-features" tabindex="-1">1.2 From Divergence to Convergence: Lock the Core Pain Point and Features <a class="header-anchor" href="#_1-2-from-divergence-to-convergence-lock-the-core-pain-point-and-features" aria-label="Permalink to “1.2 From Divergence to Convergence: Lock the Core Pain Point and Features”">​</a></h3><div class="info custom-block"><p class="custom-block-title">💡 Why &quot;convergence&quot;? What is a &quot;pain point&quot;?</p><p><strong>There are many problems. Which one do we solve first?</strong></p><p>Users can list many issues: A hurts, B hurts, C hurts. If we try to solve all of them at once, we may solve none well. So we must <strong>converge</strong>: pick the <strong>most painful, most urgent, and most solvable</strong> problem first.</p><p><strong>What is a pain point?</strong><br> It is the concrete problem users find <strong>most frustrating, most time-consuming, and most urgent to fix</strong>. Not &quot;I think this is useful,&quot; but what users complain about repeatedly in real work.</p></div><p>From interviews, we found many issues: activity-driven interruptions, multi-store management pressure, frequent context-switching between launch/pricing/creative/data tasks.</p><p>If we attempt &quot;solve all of it,&quot; we will end up with a <strong>big but unusable</strong> tool.</p><p>With AI help, we can classify the issues into three groups:</p><ol><li><strong>Rhythm problems</strong>: when to launch, when to adjust price</li><li><strong>Efficiency problems</strong>: how to manage many stores/products in parallel</li><li><strong>Content problems</strong>: how to quickly produce product images and copy</li></ol><p>For this course, the best first target is <strong>Group 3: content creation</strong>. But &quot;make content quickly&quot; is still broad, so we ask where exactly they get stuck:</p><div class="info custom-block"><p class="custom-block-title">📋 The business side says content has two biggest pain points</p><p><strong>Pain Point 1: Batch image/copy production is exhausting</strong></p><ul><li>Assets are scattered (cloud drives, chat history, backend), and <strong>hard to find</strong></li><li>Many products need launching at once, so there is <strong>no time for per-item perfection</strong></li><li>The standard is practical: <strong>good enough to launch</strong>, not perfect design</li></ul><p><strong>Pain Point 2: Good approaches are not reusable</strong></p><ul><li>Previously successful titles/layouts are <strong>hard to find next time</strong></li><li>Useful approaches are scattered in chat records and old product links</li><li>Reuse requires <strong>manual searching + copy/paste + heavy editing</strong></li><li>Missing a tool to <strong>save, manage, and apply templates directly</strong></li></ul></div><p>Based on these two pain points, we define a simple tool: <strong>help operations batch-generate image and copy drafts, and save good patterns for direct reuse next time</strong>.</p><p>The tool only focuses on two capabilities (and you can keep cutting features with AI support as business feedback arrives):</p><div class="info custom-block"><p class="custom-block-title">Feature 1: Batch generate e-commerce product images and copy</p><p><strong>What does it do?</strong><br> Given product information, the system auto-generates product images and text that can be used on platforms like Douyin and Taobao.</p><p><strong>Input</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Content</th></tr></thead><tbody><tr><td>Product data</td><td>Name, category, brand, material, size, color, target users, etc.</td></tr><tr><td>Product images</td><td>White background image or simple scene image</td></tr><tr><td>Reference assets</td><td>Screenshots/links of previously successful products</td></tr><tr><td>Import method</td><td>Excel batch import or direct form input/upload</td></tr></tbody></table><p><strong>Output (generated listing assets)</strong></p><ul><li><strong>Main product image</strong>: a presentable image draft with core selling points</li><li><strong>Product title</strong>: keyword-structured title fit for search</li><li><strong>Selling-point copy</strong>: 1-2 sentences that attract buyers</li><li>All outputs should be <strong>launch-ready or editable with light changes</strong></li></ul><p><strong>Workflow impact</strong></p><ul><li>Before: start each product&#39;s creative work from scratch</li><li>After: submit a batch, get drafts, then filter and fine-tune</li></ul></div><div class="info custom-block"><p class="custom-block-title">Feature 2: Save effective output as reusable templates</p><p><strong>Input</strong></p><table tabindex="0"><thead><tr><th>Type</th><th>Content</th></tr></thead><tbody><tr><td>A complete set</td><td>Main image + title + selling-point copy</td></tr></tbody></table><p><strong>Output</strong></p><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td>Apply</td><td>Reuse a saved template for new product generation</td></tr><tr><td>Edit</td><td>Directly edit title or copy</td></tr><tr><td>Manage</td><td>Name and tag templates (for example &quot;men&#39;s bag template&quot;, &quot;campaign title&quot;), searchable later</td></tr></tbody></table><p><strong>Workflow impact</strong></p><ol><li>Import a new product</li><li>Choose default generation or <strong>apply a saved template</strong></li><li>System applies template style and outputs a new image + copy draft</li></ol></div><hr><p><strong>What did we just do?</strong></p><ol><li><strong>Asked first</strong>: not coding immediately, but asking operators what hurts most</li><li><strong>Found core pain</strong>: &quot;image/copy creation is too labor-intensive&quot; and &quot;good patterns cannot be reused&quot;</li><li><strong>Converged scope</strong>: not building a huge platform; only two core features first</li></ol><p><strong>Why this matters</strong></p><p>A beginner trap is &quot;more features = better.&quot; In reality, users need you to solve the <strong>single most painful problem</strong> first. Many weak features are less valuable than a few features that truly work.</p><p><strong>Core product/business thinking</strong></p><ul><li>Do not decide from your assumptions</li><li>Ask users what they do daily and where it hurts most</li><li>Converge toward the most painful and solvable point</li><li>Build a <strong>minimum usable version</strong> first, then iterate</li></ul><p>This is what must be clear before coding. Code is just a tool; <strong>understanding users and locking the right problem</strong> is step one.</p>`,35)),e("div",O,[a(l,null,{default:s(()=>[a(r,{active:1,items:[{title:"Requirement Analysis",description:"From vague to concrete"},{title:"Single-Page Validation",description:"Implement the core gameplay"},{title:"Multi-Page Expansion",description:"Complete application structure"},{title:"Polish and Refine",description:"Improve user experience"}]})]),_:1})]),t[10]||(t[10]=i(`<h2 id="_2-build-a-prototype-in-10-minutes-let-ai-ide-implement-the-core-gameplay" tabindex="-1">2. Build a Prototype in 10 Minutes: Let AI IDE Implement the Core Gameplay <a class="header-anchor" href="#_2-build-a-prototype-in-10-minutes-let-ai-ide-implement-the-core-gameplay" aria-label="Permalink to “2. Build a Prototype in 10 Minutes: Let AI IDE Implement the Core Gameplay”">​</a></h2><div class="info custom-block"><p class="custom-block-title">💡 Coding plan suggestion</p><p>If your current IDE feels not smart enough, or you run out of quota quickly, consider a dedicated <strong>coding plan</strong>. You can preview <a href="./../../stage-2/backend/modern-cli/">this article</a> to use Claude for coding.</p></div><p>Thinking is good, but avoid overthinking. Let&#39;s start from one page and build a prototype first.</p><h3 id="_2-1-step-1-tell-ai-what-you-want-in-plain-language" tabindex="-1">2.1 Step 1: Tell AI What You Want in Plain Language <a class="header-anchor" href="#_2-1-step-1-tell-ai-what-you-want-in-plain-language" aria-label="Permalink to “2.1 Step 1: Tell AI What You Want in Plain Language”">​</a></h3><p>At the beginning, do not chase a perfect prompt. Start with your natural description. Explain your goal to AI as if talking to a teammate, then let AI help refine it into clearer language.</p><h4 id="_2-1-1-start-with-spoken-style-description-recommended-for-beginners" tabindex="-1">2.1.1 Start with spoken-style description (recommended for beginners) <a class="header-anchor" href="#_2-1-1-start-with-spoken-style-description-recommended-for-beginners" aria-label="Permalink to “2.1.1 Start with spoken-style description (recommended for beginners)”">​</a></h4><p>Describe your idea in your own words. Rough is fine:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to build a tool that helps e-commerce operators automatically generate product main images and copy.</span></span>
<span class="line"><span>Operators currently make images and copy one by one manually, which is painful.</span></span>
<span class="line"><span>My idea: they upload product info, and the system generates a batch of drafts.</span></span>
<span class="line"><span>Operators pick useful ones and make light edits.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Start with the simplest version: one page. Input area on the left,</span></span>
<span class="line"><span>generated results on the right. Support image upload and text fields.</span></span>
<span class="line"><span>After generation, show main image preview and copy.</span></span></code></pre></div><p>Then send this to AI (ChatGPT, Claude, etc.) and ask it to expand and structure it. AI often adds details you might miss and produces a better prompt for your AI IDE.</p><p>You can ask like this:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please expand the idea above into a clear business-logic document,</span></span>
<span class="line"><span>then generate a prompt suitable for an AI IDE (for example Cursor or Trae)</span></span>
<span class="line"><span>to generate a single-page prototype application.</span></span></code></pre></div><p>AI will return a structured requirement and prompt. Review it, remove unnecessary features, confirm it, then use it for code generation.</p><p>Why this works: your spoken description captures your true intent, but may miss key details. AI expansion can surface questions like &quot;do you need batch upload?&quot; which helps validation. Keep refining by adding/removing features until your first working prompt is solid.</p><h4 id="_2-1-2-skip-expansion-directly-give-ai-your-organized-business-doc" tabindex="-1">2.1.2 Skip expansion: directly give AI your organized business doc <a class="header-anchor" href="#_2-1-2-skip-expansion-directly-give-ai-your-organized-business-doc" aria-label="Permalink to “2.1.2 Skip expansion: directly give AI your organized business doc”">​</a></h4><p>If your business logic document is already prepared (for example from earlier chapters), you can directly feed it to the AI IDE using a structured format. This is suitable when requirements are already clear and you want to move fast.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please implement a single-page app based on the business logic below</span></span>
<span class="line"><span>to validate the core gameplay.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Business logic:</span></span>
<span class="line"><span>1. Help operations batch-generate first-round image+copy drafts:</span></span>
<span class="line"><span>- **Input (support direct upload and batch import):**</span></span>
<span class="line"><span>  - Product fields: name, category, brand, material, size, color, target users, etc.</span></span>
<span class="line"><span>  - Product image: white background image / simple scene image</span></span>
<span class="line"><span>  - Per generation, support additional uploads of historical bestseller screenshots or reference links</span></span>
<span class="line"><span>  - Support Excel batch import or direct online input/upload</span></span>
<span class="line"><span>  - Support an option to save product assets to an asset library for later use</span></span>
<span class="line"><span>- **Output (usable for listing with no or light edits):**</span></span>
<span class="line"><span>  - For each product, one &quot;acceptable, basic-selling-point&quot; main-image draft</span></span>
<span class="line"><span>  - One &quot;well-structured, keyword-containing&quot; title + 1-2 selling-point lines</span></span>
<span class="line"><span>- **Expected workflow change:**</span></span>
<span class="line"><span>  Move from writing every product from scratch to dropping batches into the system and selecting/fine-tuning generated drafts.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>First implement feature 1. Feature 2 (template library) can be added later.</span></span></code></pre></div><h4 id="_2-1-3-advanced-approach-let-ai-write-a-prompt-for-your-coding-agent" tabindex="-1">2.1.3 Advanced approach: let AI write a &quot;prompt for your coding agent&quot; <a class="header-anchor" href="#_2-1-3-advanced-approach-let-ai-write-a-prompt-for-your-coding-agent" aria-label="Permalink to “2.1.3 Advanced approach: let AI write a &quot;prompt for your coding agent&quot;”">​</a></h4><p>If you want finer control over code generation, ask AI to produce a coding-agent prompt first:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Based on the idea below, write a coding-agent prompt for me.</span></span>
<span class="line"><span>I will use it to generate code.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[paste your business logic here]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>1. Include a clear page layout description</span></span>
<span class="line"><span>2. Define data structures and interaction logic</span></span>
<span class="line"><span>3. Specify the tech stack (for example React + Tailwind)</span></span>
<span class="line"><span>4. List core features to implement</span></span></code></pre></div><p>AI will usually output a structured prompt similar to this: <img src="`+y+'" alt=""></p><p>You can then make small edits and pass it into your AI IDE.</p><h3 id="_2-2-step-2-let-ai-ide-generate-the-code-directly" tabindex="-1">2.2 Step 2: Let AI IDE Generate the Code Directly <a class="header-anchor" href="#_2-2-step-2-let-ai-ide-generate-the-code-directly" aria-label="Permalink to “2.2 Step 2: Let AI IDE Generate the Code Directly”">​</a></h3><h4 id="_2-2-1-preparation-understand-basic-ai-ide-operations" tabindex="-1">2.2.1 Preparation: understand basic AI IDE operations <a class="header-anchor" href="#_2-2-1-preparation-understand-basic-ai-ide-operations" aria-label="Permalink to “2.2.1 Preparation: understand basic AI IDE operations”">​</a></h4><p>If you are not yet familiar with AI IDEs (Cursor, Trae, Windsurf, etc.), read the appendix first: <a href="/easy-vibe/en/appendix/2-development-tools/ide-basics/">IDE Basics</a>. Learn:</p><ul><li>how to create a new project</li><li>how to chat with an AI agent</li><li>how to understand AI-generated code flow</li></ul><h4 id="_2-2-2-start-generating-code" tabindex="-1">2.2.2 Start generating code <a class="header-anchor" href="#_2-2-2-start-generating-code" aria-label="Permalink to “2.2.2 Start generating code”">​</a></h4><p>Now you already have the initial prompt. Using the first prompt style as an example, let AI help generate the project. Create/open a folder and initialize a new project:</p><p><img src="'+f+'" alt=""><img src="'+b+'" alt=""></p><p>In the sidebar, choose a model you like (for example Gemini, GPT, GLM, Kimi, MiniMax), then paste the prompt from step one:</p><p><img src="'+k+'" alt=""></p><p>After generation starts, AI will plan the folder structure, create needed files, and fill initial code.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Important: AI may pause and wait for your confirmation</p><p>During generation, the AI agent often <strong>stops and waits for your input</strong>, for example:</p><ul><li>asking whether to continue</li><li>asking you to press Enter to confirm</li><li>asking for a technical choice</li></ul><p><strong>If AI appears idle, first check the chat panel to see whether it is waiting for you.</strong><br> Many beginners think AI is &quot;thinking,&quot; but it is actually paused for input.</p></div><p>Do not forget to press Enter for confirmation where needed (some IDEs behave differently):</p><p><img src="'+w+'" alt=""></p><p>If you encounter the screen below, it usually means the local service has already started. Click skip if needed, otherwise you may stay stuck there. (If generation is done but no preview appears, ask AI directly: &quot;Please start this project.&quot;)</p><p><img src="'+v+'" alt=""></p><div class="info custom-block"><p class="custom-block-title">💡 Scenario explanation</p><p><strong>Scenario</strong>: you used <code>npm create vite@latest</code> to initialize a React + TypeScript project (<code>easy-vibe-web</code>). After creation, your computer starts a local web service so you can preview immediately.</p><p><strong>Local service</strong>: a temporary web service running only on your own machine.</p><p><strong>localhost</strong>: means &quot;this machine itself.&quot;</p><p><strong>Port</strong>: an ID for distinguishing multiple services on the same machine (this project uses port 5174).</p><p><strong>Link <code>http://localhost:5174/</code></strong>: open this in browser to view the running project.</p><p><strong>Why 5174?</strong> 5173 may already be occupied, so Vite auto-switched to 5174. This is normal.</p></div><p>After confirmation, wait briefly, and you should see the initial result:</p><p><img src="'+I+'" alt=""></p><p>The base function appears, but UI is rough. Now talk to AI directly to improve visual quality:</p><p><img src="'+x+'" alt=""></p><p>After refinement, you can get a cleaner interface:</p><p><img src="'+q+'" alt=""></p><p>Then keep iterating by need, for example:</p><ul><li>&quot;I do not need batch import now. Remove it.&quot;</li><li>&quot;The left-side form has too many fields. Keep only xxxx.&quot;</li></ul><p>You can even ask AI to reference established websites by attaching screenshots:</p><p><img src="'+A+'" alt=""></p><p>Result example:</p><p><img src="'+_+'" alt=""></p><h3 id="_2-3-what-to-do-when-errors-happen" tabindex="-1">2.3 What to Do When Errors Happen <a class="header-anchor" href="#_2-3-what-to-do-when-errors-happen" aria-label="Permalink to “2.3 What to Do When Errors Happen”">​</a></h3><p>In real practice, errors are inevitable. This is normal and does not mean you failed. You do not need to fully understand every error at once; you only need to give AI the complete observed context.</p><p>Common handling patterns:</p><ul><li><p><strong>Case 1: page or terminal errors</strong> If the page turns red, goes blank, or the terminal shows many red logs, take a screenshot or copy all error text and send it to AI.</p></li><li><p><strong>Case 2: function is wrong but no error appears</strong> For example button does nothing, data does not show, styles break. Describe in plain language: &quot;what happened&quot; + &quot;what I expected.&quot; Add screenshot if needed.</p></li><li><p><strong>Case 3: unsure whether it is a problem</strong> Ask AI directly: &quot;Please check this feature for obvious issues and suggest whether adjustments are needed.&quot;</p></li></ul><h4 id="_2-3-1-common-beginner-questions" tabindex="-1">2.3.1 Common beginner questions <a class="header-anchor" href="#_2-3-1-common-beginner-questions" aria-label="Permalink to “2.3.1 Common beginner questions”">​</a></h4><ul><li><p><strong>Q: I do not know where the error is</strong></p><ul><li>A: find all red text in terminal/console/page, copy all of it, and send to AI.</li></ul></li><li><p><strong>Q: AI fixed it, but the same error persists</strong></p><ul><li>A: very common. Send the latest error output again and ask AI to continue fixing on top of previous changes.</li></ul></li><li><p><strong>Q: Do I need to fully understand the fix immediately</strong></p><ul><li>A: no. Focus on one or two points each time. Understanding grows gradually like vocabulary learning.</li></ul></li><li><p><strong>Q: after many attempts, still broken</strong></p><ul><li>A: try these: <ul><li>use IDE version rollback in chat/history to return to a known working state</li><li>switch model or improve prompt specificity</li><li>package &quot;current code + error logs + expected behavior&quot; and ask AI to refactor that part as a whole</li></ul></li></ul></li></ul><h2 id="_3-expand-from-single-page-to-multi-page-application" tabindex="-1">3. Expand from Single-Page to Multi-Page Application <a class="header-anchor" href="#_3-expand-from-single-page-to-multi-page-application" aria-label="Permalink to “3. Expand from Single-Page to Multi-Page Application”">​</a></h2>',56)),e("div",L,[a(l,null,{default:s(()=>[a(r,{active:2,items:[{title:"Requirement Analysis",description:"From vague to concrete"},{title:"Single-Page Validation",description:"Implement the core gameplay"},{title:"Multi-Page Expansion",description:"Complete application structure"},{title:"Polish and Refine",description:"Improve user experience"}]})]),_:1})]),t[11]||(t[11]=i('<p>Once the core gameplay logic is roughly generated, we can continue building remaining pages. For example, many settings buttons may still do nothing.</p><p>You can ask AI to inspect against your business requirements and generate missing parts, or directly ask AI to implement unfinished pages one by one until all page interactions work:</p><p><img src="'+P+'" alt=""></p><p>After a short wait, you can see multiple pages and interactive features added on top of the previous base:</p><p><img src="'+C+'" alt=""><img src="'+T+'" alt=""></p><p>At this stage, manually click through the key flows you care about and confirm interactions. If something is not interactive, ask AI to fix it.</p><h2 id="_4-make-the-prototype-feel-real" tabindex="-1">4. Make the Prototype Feel Real <a class="header-anchor" href="#_4-make-the-prototype-feel-real" aria-label="Permalink to “4. Make the Prototype Feel Real”">​</a></h2>',7)),e("div",j,[a(l,null,{default:s(()=>[a(r,{active:3,items:[{title:"Requirement Analysis",description:"From vague to concrete"},{title:"Single-Page Validation",description:"Implement the core gameplay"},{title:"Multi-Page Expansion",description:"Complete application structure"},{title:"Polish and Refine",description:"Improve user experience"}]})]),_:1})]),t[12]||(t[12]=i(`<p>After multi-page structure is in place, the final step is moving from &quot;runs&quot; to &quot;feels smooth and professional.&quot; That means walking the entire user flow end to end and asking AI to fix any broken parts until you can refresh and run full flows from zero as a new user.</p><p>Let&#39;s revisit the initial requirement:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. Help operations batch-generate first-round image+copy drafts:</span></span>
<span class="line"><span>- **Input (supports direct upload and batch import):**</span></span>
<span class="line"><span>  - Product basic data: name, category, brand, material, size, color, target audience, etc.</span></span>
<span class="line"><span>  - Product image: white background / simple scene image</span></span>
<span class="line"><span>  - Per generation, support extra upload of historical bestseller screenshots or reference links</span></span>
<span class="line"><span>  - Support Excel batch import or online entry/upload</span></span>
<span class="line"><span>  - Support a page option for saving product assets to asset library for future use</span></span>
<span class="line"><span>- **Output (directly listable or listable with light edits):**</span></span>
<span class="line"><span>  - For each product, one &quot;presentable image draft with basic selling points&quot;</span></span>
<span class="line"><span>  - One &quot;well-structured, keyword-rich title&quot; + 1-2 selling-point lines</span></span>
<span class="line"><span>- **Expected workflow change:**</span></span>
<span class="line"><span>  Move from creating every batch from scratch to dropping batches into the system, then filtering and fine-tuning generated drafts.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Turn useful output into a reusable template library:</span></span>
<span class="line"><span>- **What can be saved?**</span></span>
<span class="line"><span>  - Any output judged &quot;useful&quot; by operations can be saved in one click:</span></span>
<span class="line"><span>    - full combo: main image + title + selling points</span></span>
<span class="line"><span>    - partial save: for example title pattern only or copy snippet only</span></span>
<span class="line"><span>- **What can you do after saving?**</span></span>
<span class="line"><span>  - **Reuse:**</span></span>
<span class="line"><span>    - apply saved template to a new product batch</span></span>
<span class="line"><span>    - or generate multiple variants on same product for A/B testing</span></span>
<span class="line"><span>  - **Edit:**</span></span>
<span class="line"><span>    - edit title/copy directly</span></span>
<span class="line"><span>    - if image editing is supported, adjust text/stickers on main image</span></span>
<span class="line"><span>  - **Manage:**</span></span>
<span class="line"><span>    - name and tag collections (for example &quot;men bag main image template&quot;, &quot;campaign title structure&quot;), and optionally categorize by store</span></span>
<span class="line"><span>- **How to use on next launch?**</span></span>
<span class="line"><span>  - after importing new products, operations can choose:</span></span>
<span class="line"><span>    - default system generation, or</span></span>
<span class="line"><span>    - &quot;generate using my saved template&quot;</span></span>
<span class="line"><span>  - system applies template structure/style to new product data and outputs new main image + title + selling-point drafts</span></span></code></pre></div><p>If each test requires manual setup from scratch, testing becomes expensive. In practice we often create <strong>test data entry points</strong> to accelerate full-flow testing. You can ask AI:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I need to test the full user journey and ensure everything works end to end.</span></span>
<span class="line"><span>Please generate test-data shortcuts based on the requirement below so I can quickly validate the entire flow:</span></span>
<span class="line"><span>1. Help operations batch-generate first-round image+copy drafts:</span></span>
<span class="line"><span>- **Input (supports direct upload and batch import):**</span></span>
<span class="line"><span>  - Product basic data: name, category, brand, material, size, color, target audience, etc.</span></span>
<span class="line"><span>  - Product image: white background / simple scene image</span></span>
<span class="line"><span>  - Per generation, support extra upload of historical bestseller screenshots or reference links</span></span>
<span class="line"><span>  - Support Excel batch import or online entry/upload</span></span>
<span class="line"><span>  - Support a page option for saving product assets to asset library for future use</span></span>
<span class="line"><span>- **Output (directly listable or listable with light edits):**</span></span>
<span class="line"><span>  - For each product, one &quot;presentable image draft with basic selling points&quot;</span></span>
<span class="line"><span>  - One &quot;well-structured, keyword-rich title&quot; + 1-2 selling-point lines</span></span>
<span class="line"><span>- **Expected workflow change:**</span></span>
<span class="line"><span>  Move from creating every batch from scratch to dropping batches into the system, then filtering and fine-tuning generated drafts.</span></span></code></pre></div><p>You can quickly get a usable result (and if one case is not enough, ask AI to generate multiple test cases):</p><p><img src="`+S+'" alt=""></p><p>Click to test:</p><p><img src="'+E+'" alt=""></p><p>At this point, the result may appear immediately without a simulated generation process. If you want realistic delay/feedback, ask AI:</p><p>&quot;Please simulate a real generation process so after clicking, results appear after a short delay.&quot;</p><p><img src="'+D+'" alt=""></p><p>After generation flow works, verify template-library behavior. If the &quot;save template&quot; interaction is missing, ask AI:</p><p>&quot;Please ensure requirement 2 works correctly: I can save a generated result as a template, open it, and view generation parameters.&quot;</p><p>Generation is usually iterative, and screenshots are often needed for correction:</p><p><img src="'+W+'" alt=""></p><p>Expected final result:</p><p><img src="'+B+'" alt=""></p><p>Besides manual user-flow testing, you can also ask AI to do requirement coverage checks:</p><ul><li>&quot;Compare this app against my original requirement. Are all core features covered?&quot;</li><li>&quot;Give me a checklist: completed, missing, and weak-experience parts.&quot;</li></ul><p>AI will usually return a checklist. Use it to decide whether to continue iterating. After several rounds, you can get a much stronger prototype.</p><h2 id="_5-📚-assignment-recreate-your-own-douyin-e-commerce-workbench" tabindex="-1">5. 📚 Assignment: Recreate Your Own Douyin E-commerce Workbench <a class="header-anchor" href="#_5-📚-assignment-recreate-your-own-douyin-e-commerce-workbench" aria-label="Permalink to “5. 📚 Assignment: Recreate Your Own Douyin E-commerce Workbench”">​</a></h2>',22)),a(p,{shadow:"hover",style:{margin:"20px 0","border-radius":"12px"}},{header:s(()=>[...t[2]||(t[2]=[e("div",{style:{"font-weight":"bold","font-size":"16px"}},"🚀 Challenge Task: Recreate an E-commerce Asset Workbench",-1)])]),default:s(()=>[t[3]||(t[3]=e("p",null," Follow this chapter's approach and complete one full loop: ",-1)),t[4]||(t[4]=e("ul",null,[e("li",null,[e("strong",null,"Full-loop practice"),e("ul",null,[e("li",null,"Business requirement prompt generation → single-page prototype generation → multi-page prototype generation")])]),e("li",null,[e("strong",null,"Share your result"),e("ul",null,[e("li",null,"Take screenshots of your application and share them with everyone")])]),e("li",null,[e("strong",null,"Thinking question"),e("ul",null,[e("li",null,'Reserve space for next chapter ("Integrating LLM and text-to-image capabilities"). Think in advance: how can your workbench embed AI copywriting, image generation, and script generation?')])])],-1))]),_:1}),t[13]||(t[13]=e("h2",{id:"next-step",tabindex:"-1"},[n("Next Step "),e("a",{class:"header-anchor",href:"#next-step","aria-label":"Permalink to “Next Step”"},"​")],-1)),t[14]||(t[14]=e("p",null,"In the next chapter, on top of this content-production workbench, we will integrate concrete AI capabilities (text-to-text, image-to-text, text-to-image), for example:",-1)),t[15]||(t[15]=e("ul",null,[e("li",null,"Auto-generate first-draft copy and multiple title candidates for a given content task"),e("li",null,"Auto-generate visual drafts from task descriptions (text-to-image)"),e("li",null,"Auto-classify and summarize historical tasks to help plan the next campaign theme")],-1)),a(g,{title:"Continue Learning",description:"Recommended order: integrate AI capabilities -> complete full project loop -> design engineering.",items:F(c)},null,8,["items"])])}}});export{G as __pageData,U as default};
